package com.pratik.imagetap;
import android.app.*;import android.widget.*;
final class PresetEditor {
 static void open(Activity a,Runnable changed){
  LinearLayout form=Ui.column(a);int p=Ui.dp(a,18);form.setPadding(p,p,p,p);form.addView(Ui.label(a,"Each slot keeps its own images and image options automatically. Global scan settings and screen regions stay shared.",13,Ui.MUTED));
  ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(ActionType.selected(a).label+" · Three presets").setView(scroll).setNegativeButton("Done",null).create();
  for(int i=0;i<PresetStore.COUNT;i++){final int slot=i;String name=PresetStore.name(a,i);TextView slotTitle=Ui.label(a,(PresetStore.active(a)==i?"● ":"")+name+" · "+PresetStore.files(PresetStore.folder(a,i)).size()+" images",16,Ui.TEXT);slotTitle.setPadding(0,Ui.dp(a,20),0,Ui.dp(a,12));form.addView(slotTitle);LinearLayout row=new LinearLayout(a);form.addView(row);
   Button use=Ui.button(a,"Open",false),rename=Ui.button(a,"Rename",false),save=Ui.button(a,"Save here",false);for(Button b:new Button[]{use,rename,save}){b.setTextSize(11);b.setPadding(Ui.dp(a,4),Ui.dp(a,8),Ui.dp(a,4),Ui.dp(a,8));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,Ui.dp(a,48),1);if(row.getChildCount()>0)bp.leftMargin=Ui.dp(a,8);row.addView(b,bp);}
   use.setOnClickListener(v->{PresetStore.open(a,slot);if(TapService.instance!=null)TapService.instance.refreshTargets();dialog.dismiss();changed.run();});
   rename.setOnClickListener(v->nameDialog(a,slot,false,dialog,changed));save.setOnClickListener(v->nameDialog(a,slot,true,dialog,changed));
  }
  TextView share=Ui.label(a,"SHARE A COLLECTION",11,Ui.accent(1));share.setLetterSpacing(.1f);share.setPadding(0,Ui.dp(a,24),0,Ui.dp(a,12));form.addView(share);LinearLayout transfer=new LinearLayout(a);form.addView(transfer);Button export=Ui.button(a,"Export current",false),load=Ui.button(a,"Import file",false);transfer.addView(export,new LinearLayout.LayoutParams(0,Ui.dp(a,52),1));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,Ui.dp(a,52),1);ip.leftMargin=Ui.dp(a,8);transfer.addView(load,ip);export.setOnClickListener(v->{dialog.dismiss();PresetTransferActivity.launch(a,true);});load.setOnClickListener(v->{dialog.dismiss();PresetTransferActivity.launch(a,false);});dialog.show();
 }
 static void nameDialog(Activity a,int slot,boolean copy,AlertDialog parent,Runnable changed){EditText name=new EditText(a);name.setSingleLine(true);name.setText(PresetStore.name(a,slot));AlertDialog d=new AlertDialog.Builder(a).setTitle(copy?"Save current set to slot "+(slot+1):"Rename preset").setMessage(copy?"This replaces the selected slot's saved set. Your current collection stays intact.":"Choose a name for this collection.").setView(name).setNegativeButton("Cancel",null).setPositiveButton(copy?"Save":"Rename",null).create();d.show();d.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()){name.setError("Enter a name");return;}d.dismiss();parent.dismiss();if(TapService.instance!=null)TapService.instance.refreshTargets();ProgressDialog busy=new ProgressDialog(a);busy.setMessage(copy?"Saving preset…":"Renaming…");busy.setCancelable(false);busy.show();android.content.Context scope=ActionType.scope(a,ActionType.selected(a));new Thread(()->{String error=null;try{if(copy)PresetStore.copyCurrent(scope,slot,n);else PresetStore.rename(scope,slot,n);}catch(Exception e){error=e.getMessage();}String result=error;a.runOnUiThread(()->{if(!a.isDestroyed()){busy.dismiss();if(result!=null)Toast.makeText(a,result,Toast.LENGTH_LONG).show();else{if(TapService.instance!=null)TapService.instance.refreshTargets();changed.run();}}});},"preset-save").start();});}
}
